from config import BucketConfig
from bucket import TokenBucket

class RateLimiter:
    def __init__(self, capacity: float, refill_rate: float):
        self.bucket = TokenBucket(BucketConfig(capacity=capacity, refill_rate=refill_rate))

    def allow_request(self, tokens: float, timestamp: float) -> bool:
        return self.bucket.consume(tokens, timestamp)

